mapper.select:
SELECT o.organization_code, o.organization_name, o.organization_type, o.use_status, current_relation.parent_organization_code AS current_parent_organization_code FROM organization o LEFT JOIN LATERAL ( SELECT parent_organization_code FROM organization_relation_history WHERE organization_code = o.organization_code AND status = 'ACTIVE' AND effective_start_date <= CURRENT_DATE AND (effective_end_date IS NULL OR effective_end_date >= CURRENT_DATE) ORDER BY effective_start_date DESC LIMIT 1 ) current_relation ON TRUE WHERE o.use_status = 'ACTIVE'
AND o.organization_code ILIKE CONCAT('%', #{organizationCode}, '%')
ORDER BY o.organization_code LIMIT #{limit} OFFSET #{offset}

SELECT o.organization_code, o.organization_name, o.organization_type, o.use_status,
  NULL AS current_parent_organization_code
FROM organization o WHERE o.organization_code = #{organizationCode}
